import java.util.*;

import jakarta.persistence.*;
import org.hibernate.cfg.Configuration;

public class Main {
    public static void main(String[] args) {
        EntityManagerFactory emf = Jpa.buat(false, Produk.class);
        EntityManager em = emf.createEntityManager();
        em.getTransaction().begin();
        em.persist(new Produk("Kopi Susu", "minuman", 18000));
        em.persist(new Produk("Teh Manis", "minuman", 8000));
        em.persist(new Produk("Croissant", "roti", 25000));
        em.persist(new Produk("Roti Bakar", "roti", 15000));
        em.persist(new Produk("Air Mineral", "minuman", 5000));
        em.getTransaction().commit();
        String kata = "' or '1'='1";
        List<Produk> aman = em.createQuery("select p from Produk p where p.nama = :nama", Produk.class)
                .setParameter("nama", kata)
                .getResultList();
        System.out.println("Dengan parameter: " + aman.size());
        List<Produk> bahaya = em.createQuery("select p from Produk p where p.nama = '" + kata + "'", Produk.class).getResultList();
        System.out.println("Disambung: " + bahaya.size());
        em.close();
        emf.close();
    }
}

@Entity
class Produk {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String nama;

    private String kategori;

    private int harga;

    protected Produk() {
    }

    Produk(String nama, String kategori, int harga) {
        this.nama = nama;
        this.kategori = kategori;
        this.harga = harga;
    }

    String getNama() {
        return nama;
    }

    int getHarga() {
        return harga;
    }

    void naikkan(int persen) {
        harga += harga * persen / 100;
    }
}

class Jpa {
    static EntityManagerFactory buat(boolean tampilkanSql, Class<?>... entity) {
        Configuration cfg = new Configuration()
                .setProperty("hibernate.connection.url", "jdbc:h2:mem:toko;DB_CLOSE_DELAY=-1")
                .setProperty("hibernate.connection.username", "sa")
                .setProperty("hibernate.hbm2ddl.auto", "create")
                .setProperty("hibernate.show_sql", String.valueOf(tampilkanSql));
        for (Class<?> k : entity) {
            cfg.addAnnotatedClass(k);
        }
        return cfg.buildSessionFactory();
    }
}

